local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local ImageComp = CS.UnityEngine.UI.Image
local LoopType = CS.DG.Tweening.LoopType
local KTool = CS.Engine.Lib.KTool

---@class ScreenShineEffect : BaseEffect
local ScreenShineEffect = Class("ScreenShineEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")

function ScreenShineEffect:__init()
    self.TargetColor = nil
    self.StartColor = nil
    self.PrevColor = nil
    self._isFinish = nil
    self.Duration = 0.25
end

function ScreenShineEffect:__delete()
    self.TargetColor = nil
    self.StartColor = nil
    self.PrevColor = nil
    self._isFinish = nil
    self.Duration = nil
end

---@param parameters NewChapter2DVo
function ScreenShineEffect:Initialize(parameters)
    base.Initialize(self, parameters)
    if parameters.screenAnim == NewChapterConstants.ScreenEffect.WhiteShining then
        self.TargetColor = Color.New(1,1,1,1)
        self.StartColor = Color.New(1,1,1,0)
    end
end

function ScreenShineEffect:StartEffect(object)
    base.StartEffect(self, object)

    if not KTool.IsActiveInHierarchy(object.gameObject) then
        KTool.SetActive(object.gameObject, true)
        KTool.SetActive(object.transform.parent, true)
    end
    
    local img = object.gameObject:GetComponent(typeof(ImageComp))
    self._isFinish = false
    if isNull(img) then
       return 
    end
    self.PrevColor = img.color
    img.color = self.StartColor
    self.tween = img:DOColor(self.TargetColor, self.Duration):SetLoops(5, LoopType.Yoyo):OnComplete(function()
        self._isFinish = true
    end)
end

function ScreenShineEffect:IsFinish()
    base.IsFinish(self)
    return self._isFinish
end

function ScreenShineEffect:EndEffect(object)
    base.EndEffect(self, object)
    local img = object.gameObject:GetComponent(typeof(ImageComp))
    if isNull(img) then
        return
    end
    if not self.Tween:IsComplete() then
        self.Tween:Complete()
        self.Tween = nil
    end

    self._isFinish = true
    img.color = self.StartColor
end

function ScreenShineEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)

    if KTool.IsActiveInHierarchy(object.gameObject) then
        KTool.SetActive(object.gameObject, false)
        KTool.SetActive(object.transform.parent, false)
    end
    
    local img = object.gameObject:GetComponent(typeof(ImageComp))
    if isNull(img) then
        return
    end
    img.color = self.PrevColor
end

return ScreenShineEffect